<?php require '../includes/functions.php'; if(!empty($_SESSION['admin_id'])) redirect('index.php'); if($_SERVER['REQUEST_METHOD']==='POST'){ $stmt=$pdo->prepare('SELECT * FROM admins WHERE username=?');$stmt->execute([$_POST['username']]);$a=$stmt->fetch(); if($a && (password_verify($_POST['password'],$a['password']) || $_POST['password']===$a['password'])){ if($_POST['password']===$a['password']) $pdo->prepare('UPDATE admins SET password=? WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$a['id']]); $_SESSION['admin_id']=$a['id'];redirect('index.php');} $error='Invalid admin account.'; } ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin Login</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body class="soft-yellow"><main class="section-pad"><div class="container"><div class="row justify-content-center"><div class="col-md-4"><form method="post" class="bg-white p-4 rounded-4 shadow"><div class="text-center"><img src="../assets/images/logo.svg" width="95" alt="logo"><h2 class="fw-bold">Admin Login</h2></div><?php if(!empty($error)): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><input name="username" class="form-control mb-3" placeholder="Username" required><input name="password" type="password" class="form-control mb-3" placeholder="Password" required><button class="btn btn-red w-100">Login</button><p class="small text-muted mt-3">Default: admin / admin123</p></form></div></div></div></main></body></html>